#!/usr/bin/env python3
"""News image for make.fun competition news-image-20261121 (v6).

Draws a newspaper front page summing up Saturday 21 November 2026
with pure Python 3.13 standard library only (no network, no fonts on
disk).  Real print type: Liberation Sans/Serif glyphs rasterized at
build time by the builder's own script and embedded below as a
compressed blob; at runtime the program just decodes it and
alpha-blits the glyphs, so two runs write byte-identical files.

v6 method (from the gap study vs top-1 samatch-we 99.19% and top-2
asell 99.09%; our v5 scored 97.47% at rank #1,237): keep v5's proven
skeleton -- same masthead, stat strip, region bar, 3 leads + 10
mediums, same 35 stories and facts -- and fix what the study showed
was thin: (1) body copy 2-3 lines per lead and 2 lines per medium,
every story with its source in parentheses; (2) denser illustrations
that fill each panel instead of leaving empty space; (3) a real world
map with numbered pins for all 35 stories spread over every
continent; (4) verification chips (OFFICIAL / CONFIRMED / REPORTED /
CLAIM) on the medium cards, as top-2 does; (5) a fuller footer
attribution line.  Panels stay big (leads ~104px, mediums ~54px):
thin strips are what cost v4 its score.
"""

