def _load_fonts():
    data = zlib.decompress(base64.b64decode("".join(GLYPH_BLOB.split())))
    assert data[:3] == b"NF2"
    pos = 3
    n = data[pos]
    pos += 1
    fonts = {}
    for key in FONT_KEYS[:n]:
        ascent, descent = data[pos], data[pos + 1]
        pos += 2
        glyphs = {}
        for ch in CHARSET:
            adv = data[pos]
            x0 = data[pos + 1] - 128
            y0 = data[pos + 2] - 128
            w, h = data[pos + 3], data[pos + 4]
            pos += 5
            bmp = bytes(data[pos:pos + w * h])
            pos += w * h
            glyphs[ch] = (adv, x0, y0, w, h, bmp)
        fonts[key] = (ascent, descent, glyphs)
    assert pos == len(data)
    return fonts


FONTS = _load_fonts()


def line_h(font):
    ascent, descent, _ = FONTS[font]
    return ascent + descent


# ------------------------------------------------------------ canvas
PAPER = (247, 243, 232)
INK = (20, 20, 20)
NAVY = (20, 33, 61)
NAVY2 = (28, 48, 88)
RED = (185, 28, 28)
RED2 = (220, 38, 38)
BLUE = (29, 78, 216)
TEAL = (13, 116, 128)
GOLD = (180, 130, 20)
GREEN = (34, 139, 34)
PURPLE = (90, 60, 140)
WHITE = (255, 255, 255)
GREY = (90, 90, 90)
DARKGREY = (60, 60, 60)
LIGHT = (238, 232, 216)
MIDGREY = (200, 194, 178)


class Canvas:
    """RGB canvas with fill/line/circle/polygon primitives."""

    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.px = bytearray(bg * (w * h))

    def set(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.px[i], self.px[i + 1], self.px[i + 2] = c

    def blit(self, x, y, w, h, bmp, color):
        r, g, b = color
        px = self.px
        W = self.w
        H = self.h
        for row in range(h):
            yy = y + row
            if yy < 0 or yy >= H:
                continue
            base = row * w
            for col in range(w):
                a = bmp[base + col]
                if a == 0:
                    continue
                xx = x + col
                if xx < 0 or xx >= W:
                    continue
                i = (yy * W + xx) * 3
                if a == 255:
                    px[i], px[i + 1], px[i + 2] = r, g, b
                else:
                    px[i] = (a * r + (255 - a) * px[i]) // 255
                    px[i + 1] = (a * g + (255 - a) * px[i + 1]) // 255
                    px[i + 2] = (a * b + (255 - a) * px[i + 2]) // 255

    def fill(self, x, y, w, h, c):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        for yy in range(y0, y1):
            base = (yy * self.w + x0) * 3
            for xx in range(x0, x1):
                i = base + (xx - x0) * 3
                self.px[i], self.px[i + 1], self.px[i + 2] = c

    def rect(self, x, y, w, h, c, t=1):
        self.fill(x, y, w, t, c)
        self.fill(x, y + h - t, w, t, c)
        self.fill(x, y, t, h, c)
        self.fill(x + w - t, y, t, h, c)

    def hline(self, x, y, w, c, t=1):
        self.fill(x, y, w, t, c)

    def vline(self, x, y, h, c, t=1):
        self.fill(x, y, t, h, c)

    def line(self, x0, y0, x1, y1, c, t=1):
        dx = x1 - x0
        dy = y1 - y0
        steps = max(abs(dx), abs(dy), 1)
        for s in range(steps + 1):
            x = x0 + dx * s // steps
            y = y0 + dy * s // steps
            self.fill(x - t // 2, y - t // 2, t, t, c)

    def circle(self, cx, cy, r, c, filled=True):
        for yy in range(cy - r, cy + r + 1):
            for xx in range(cx - r, cx + r + 1):
                d = (xx - cx) ** 2 + (yy - cy) ** 2
                if filled:
                    if d <= r * r:
                        self.set(xx, yy, c)
                else:
                    if r * r - 2 * r <= d <= r * r:
                        self.set(xx, yy, c)

    def poly(self, pts, c):
        ys = [p[1] for p in pts]
        for y in range(min(ys), max(ys) + 1):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    xs.append(x0 + (y - y0) * (x1 - x0) // (y1 - y0))
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                for x in range(xs[k], xs[k + 1] + 1):
                    self.set(x, y, c)


# ------------------------------------------------------------ text
def text_w(s, font):
    _, _, glyphs = FONTS[font]
    q = glyphs["?"]
    return sum(glyphs.get(ch, q)[0] for ch in s)


def draw_text(cv, x, y, s, font, color):
    """Draw text; y is the top of the line (top of the ascender)."""
    _, _, glyphs = FONTS[font]
    q = glyphs["?"]
    for ch in s:
        adv, x0, y0, w, h, bmp = glyphs.get(ch, q)
        if w and h:
            cv.blit(x + x0, y + y0, w, h, bmp, color)
        x += adv
    return x


def draw_text_centered(cv, cx, y, s, font, color):
    draw_text(cv, cx - text_w(s, font) // 2, y, s, font, color)


def wrap(s, max_w, font):
    words = s.split(" ")
    lines = []
    cur = ""
    for word in words:
        trial = word if not cur else cur + " " + word
        if text_w(trial, font) <= max_w or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


def draw_para(cv, x, y, s, max_w, font, color, leading=None):
    if leading is None:
        leading = line_h(font)
    lines = wrap(s, max_w, font)
    for ln in lines:
        draw_text(cv, x, y, ln, font, color)
        y += leading
    return y


# ------------------------------------------------------------ png
def png_bytes(cv):
    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)
        raw += cv.px[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 6)

    def chunk(tag, data):
        out = struct.pack(">I", len(data)) + tag + data
        out += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", comp) + chunk(b"IEND", b""))


# ------------------------------------------------------------ scenes
# v6: every panel is drawn DENSE -- the subject fills the frame, no
# empty corners.  Geometry is proportional to (w, h).  The red banner
# is drawn over the top of each panel by the layout code, so scenes
# keep their main subject out of the top-left corner; medium chips
# sit bottom-right, so scenes keep that corner quiet too.
def scene_cop31(cv, x, y, w, h):
    # Climate summit: big globe with continents, thermometer, clock,
    # rising sun, ground line.
    cv.fill(x, y, w, h, (198, 226, 200))
    cv.circle(x + int(w * 0.82), y + int(h * 0.16), int(h * 0.13),
              (250, 210, 90))
    cx, cy, r = x + int(w * 0.17), y + h // 2 + 2, int(h * 0.32)
    cv.circle(cx, cy, r, BLUE)
    cv.circle(cx - r // 3, cy - r // 4, r // 3, GREEN)
    cv.circle(cx + r // 3, cy + r // 3, r // 4, GREEN)
    cv.circle(cx + r // 4, cy - r // 2, r // 5, GREEN)
    cv.circle(cx - r // 2, cy + r // 2, r // 6, GREEN)
    cv.hline(cx - r, cy, 2 * r, WHITE, 2)
    kx, ky, kr = x + int(w * 0.55), y + int(h * 0.30), int(h * 0.20)
    cv.circle(kx, ky, kr, WHITE)
    cv.circle(kx, ky, kr, INK, filled=False)
    cv.line(kx, ky, kx, ky - kr + 4, INK, 2)
    cv.line(kx, ky, kx + kr // 2, ky + kr // 4, INK, 2)
    tx = x + int(w * 0.88)
    tw = max(8, int(w * 0.035))
    cv.fill(tx, y + int(h * 0.10), tw, int(h * 0.68), WHITE)
    cv.rect(tx, y + int(h * 0.10), tw, int(h * 0.68), INK, 1)
    cv.fill(tx + 2, y + int(h * 0.30), tw - 4, int(h * 0.48), RED2)
    cv.circle(tx + tw // 2, y + int(h * 0.82), int(h * 0.11), RED2)
    cv.hline(x, y + h - 3, w, (120, 170, 125), 2)
    for gx in range(x + 6, x + w - 6, 22):
        cv.set(gx, y + h - 8, (90, 140, 95))
        cv.set(gx + 1, y + h - 8, (90, 140, 95))


def scene_riyadh(cv, x, y, w, h):
    # Night skyline with lit windows, five missile trails, two
    # intercept bursts, moon.
    cv.fill(x, y, w, h, NAVY)
    for sx in range(x + 8, x + w - 8, 12):
        for sy in range(y + 8, y + int(h * 0.55), 10):
            if (sx * 7 + sy * 13) % 23 < 8:
                cv.set(sx, sy, (255, 220, 130))
    fracs = [0.50, 0.72, 0.42, 0.85, 0.55, 0.92, 0.48, 0.68,
             0.55, 0.78, 0.45, 0.65]
    bw = w // len(fracs)
    for i, f in enumerate(fracs):
        bh = int(h * f)
        bx = x + i * bw
        cv.fill(bx + 1, y + h - bh, bw - 2, bh, (10, 16, 32))
        for wy in range(y + h - bh + 5, y + h - 5, 9):
            for wx in range(bx + 4, bx + bw - 4, 7):
                if (wx + wy) % 11 < 4:
                    cv.set(wx, wy, (255, 210, 110))
    trails = ((x + w - 24, y + 8, x + w - 110, y + 42),
              (x + w - 70, y + 4, x + w - 170, y + 38),
              (x + w - 8, y + 28, x + w - 90, y + 56),
              (x + w - 120, y + 6, x + w - 200, y + 34),
              (x + w - 46, y + 16, x + w - 140, y + 50))
    for (sx, sy, ex, ey) in trails:
        cv.line(sx, sy, ex, ey, (255, 140, 60), 2)
        cv.circle(ex, ey, 4, (255, 200, 80))
        cv.circle(ex, ey, 2, (255, 240, 160))
    for (bx, by) in ((x + w - 110, y + 42), (x + w - 90, y + 56)):
        for (dx, dy) in ((0, -7), (6, -3), (6, 4), (0, 7), (-6, 4),
                          (-6, -3), (0, 0)):
            cv.set(bx + dx, by + dy, (255, 240, 160))
    cv.circle(x + 28, y + 22, int(h * 0.13), (240, 230, 190))


def scene_peru(cv, x, y, w, h):
    # Andes, red seismograph trace across the whole panel, two houses.
    cv.fill(x, y, w, h, (232, 214, 170))
    cv.circle(x + int(w * 0.12), y + int(h * 0.18), int(h * 0.10),
              (250, 220, 130))
    cv.poly([(x, y + h), (x + int(w * 0.28), y + int(h * 0.16)),
             (x + int(w * 0.56), y + h)], (150, 110, 70))
    cv.poly([(x + int(w * 0.44), y + h), (x + int(w * 0.75), y + int(h * 0.22)),
             (x + w, y + h)], (120, 88, 55))
    cv.poly([(x + int(w * 0.60), y + h), (x + int(w * 0.82), y + int(h * 0.45)),
             (x + w, y + h)], (135, 98, 60))
    mid = y + int(h * 0.30)
    amp = int(h * 0.16)
    xs = [0.03, 0.13, 0.17, 0.21, 0.25, 0.29, 0.33, 0.47, 0.51, 0.55,
          0.59, 0.63, 0.97]
    ys = [0, 0, -amp, amp, -amp // 2, amp // 2, 0, 0, -amp, amp, 0, 0, 0]
    pts = [(x + int(fx * w), mid + dy) for fx, dy in zip(xs, ys)]
    for a, b in zip(pts, pts[1:]):
        cv.line(a[0], a[1], b[0], b[1], RED2, 2)
    for hx, hy, hw, hh in ((x + int(w * 0.78), y + h - int(h * 0.26),
                            int(w * 0.16), int(h * 0.26)),
                           (x + int(w * 0.58), y + h - int(h * 0.18),
                            int(w * 0.11), int(h * 0.18))):
        cv.fill(hx, hy, hw, hh, WHITE)
        cv.poly([(hx - 4, hy), (hx + hw // 2, hy - int(h * 0.10)),
                 (hx + hw + 4, hy)], RED)
        cv.fill(hx + hw // 2 - 3, hy + hh // 2, 6, hh // 2, INK)


def scene_kyiv(cv, x, y, w, h):
    # Blue over yellow, dark skyline, warning star, person silhouette.
    cv.fill(x, y, w, h // 2 + 2, (0, 91, 172))
    cv.fill(x, y + h // 2, w, h - h // 2, (255, 213, 0))
    for i, bh in enumerate((int(h * 0.36), int(h * 0.56), int(h * 0.30),
                            int(h * 0.64), int(h * 0.42))):
        bx = x + 8 + i * (w // 5)
        cv.fill(bx, y + h - bh - 2, w // 5 - 8, bh, INK)
        for wy in range(y + h - bh + 3, y + h - 6, 8):
            cv.set(bx + 4, wy, (255, 213, 0))
    cv.circle(x + w - 18, y + 12, int(h * 0.18), WHITE)
    cv.circle(x + w - 18, y + 12, int(h * 0.14), RED2)
    px, py = x + 16, y + h - int(h * 0.30)
    cv.circle(px, py - 8, 4, INK)
    cv.fill(px - 3, py - 4, 6, 12, INK)


def scene_hormuz(cv, x, y, w, h):
    # Strait: sea, waves, tanker, drone, sun.
    cv.fill(x, y, w, h, (120, 190, 220))
    cv.fill(x, y + h - int(h * 0.16), w, int(h * 0.16), (20, 80, 140))
    for wx in range(x + 4, x + w - 4, 18):
        cv.hline(wx, y + h - int(h * 0.10), 10, (160, 210, 240), 1)
    cv.circle(x + w - 20, y + 10, int(h * 0.22), (255, 220, 120))
    sx, sy = x + 14, y + h - int(h * 0.36)
    cv.fill(sx, sy, int(w * 0.60), int(h * 0.22), (40, 40, 40))
    cv.fill(sx + int(w * 0.38), sy - int(h * 0.20), int(w * 0.12),
            int(h * 0.20), (40, 40, 40))
    cv.fill(sx + int(w * 0.41), sy - int(h * 0.30), 4, int(h * 0.12), RED2)
    cv.fill(sx + 6, sy + 3, 10, 4, (200, 200, 200))
    dx, dy = x + w // 2 + 20, y + 10
    cv.fill(dx - 10, dy, 20, 4, INK)
    cv.fill(dx - 2, dy - 2, 4, 9, INK)
    cv.fill(dx - 15, dy - 3, 10, 2, INK)
    cv.fill(dx + 5, dy - 3, 10, 2, INK)
    cv.circle(dx, dy + 8, 2, RED2)


def scene_iran(cv, x, y, w, h):
    # Atom over a dome and minaret.
    cv.fill(x, y, w, h, (30, 30, 48))
    cx, cy = x + w // 2, y + int(h * 0.60)
    for r in (int(h * 0.34), int(h * 0.24), int(h * 0.14)):
        cv.circle(cx, cy, r, GOLD, filled=False)
    cv.circle(cx, cy, 3, WHITE)
    cv.fill(cx - 2, cy - int(h * 0.34), 4, 6, GOLD)
    cv.line(cx - int(h * 0.30), cy, cx + int(h * 0.30), cy, GOLD, 1)
    cv.poly([(x + 14, y + h), (cx, y + h - int(h * 0.30)),
             (x + w - 14, y + h)], (90, 90, 110))
    mx = x + w - 18
    cv.fill(mx, y + h - int(h * 0.55), 5, int(h * 0.55), (120, 120, 140))
    cv.circle(mx + 2, y + h - int(h * 0.58), 4, (120, 120, 140))


def scene_aitax(cv, x, y, w, h):
    # AI chip on a dark board with server racks either side.
    cv.fill(x, y, w, h, (16, 24, 64))
    for rx in (x + 6, x + w - 16):
        cv.fill(rx, y + 6, 10, h - 12, (30, 40, 80))
        for ry in range(y + 10, y + h - 8, 8):
            cv.set(rx + 2, ry, (90, 200, 120))
            cv.set(rx + 6, ry, (90, 200, 120))
    cx, cy = x + w // 2, y + h // 2 + 2
    cw, ch = int(w * 0.30), int(h * 0.62)
    cv.fill(cx - cw // 2, cy - ch // 2, cw, ch, (10, 10, 14))
    cv.rect(cx - cw // 2, cy - ch // 2, cw, ch, GOLD, 2)
    for k in range(-1, 2):
        cv.fill(cx - cw // 2 - 5, cy + k * 8 - 1, 5, 2, GOLD)
        cv.fill(cx + cw // 2, cy + k * 8 - 1, 5, 2, GOLD)
    draw_text(cv, cx - text_w("AI", "B26") // 2, cy - 9, "AI", "B26", WHITE)


def scene_chinajapan(cv, x, y, w, h):
    # China red with stars, Japan white with sun, divider.
    cv.fill(x, y, w // 2, h, (222, 0, 41))
    cv.fill(x + w // 2, y, w - w // 2, h, WHITE)
    for sx, sy in ((10, 8), (24, 12), (30, 24), (14, 26)):
        cv.circle(x + sx, y + sy, 3, (255, 222, 0))
    cv.circle(x + w // 2 + (w - w // 2) // 2, y + h // 2,
              int(h * 0.30), (188, 0, 45))
    cv.vline(x + w // 2, y, h, INK, 2)


def scene_davao(cv, x, y, w, h):
    # Jet on approach over the runway, clouds, control tower.
    cv.fill(x, y, w, h, (140, 200, 235))
    cv.circle(x + 22, y + 12, 8, WHITE)
    cv.circle(x + 34, y + 10, 10, WHITE)
    cv.circle(x + w - 30, y + 14, 7, WHITE)
    cv.fill(x, y + h - int(h * 0.20), w, int(h * 0.20), (60, 120, 60))
    cv.fill(x, y + h - int(h * 0.24), w, 2, (40, 40, 40))
    for wx in range(x + 8, x + w - 8, 24):
        cv.fill(wx, y + h - int(h * 0.12), 12, 2, WHITE)
    tx = x + w - 22
    cv.fill(tx, y + h - int(h * 0.52), 6, int(h * 0.32), (90, 90, 90))
    cv.fill(tx - 4, y + h - int(h * 0.58), 14, 6, (90, 90, 90))
    fx, fy = x + w // 2, y + h // 2
    cv.fill(fx - 62, fy - 4, 124, 8, WHITE)
    cv.poly([(fx - 12, fy - 4), (fx + 16, fy - 20), (fx + 30, fy - 20),
             (fx + 12, fy - 4)], WHITE)
    cv.poly([(fx - 36, fy + 4), (fx - 52, fy + 18), (fx - 36, fy + 18),
             (fx - 20, fy + 4)], WHITE)
    cv.poly([(fx + 54, fy - 4), (fx + 68, fy - 16), (fx + 72, fy - 16),
             (fx + 64, fy - 4)], WHITE)
    cv.circle(fx + 52, fy, 3, BLUE)


def scene_canberra(cv, x, y, w, h):
    # Two flags side by side: Australia blue, China red, gold base.
    cv.fill(x, y, w // 2, h, (0, 40, 120))
    cv.fill(x + w // 2, y, w - w // 2, h, (222, 0, 41))
    for sx, sy in ((16, 10), (34, 18), (20, 28), (40, 10)):
        cv.circle(x + sx, y + sy, 3, WHITE)
    cv.fill(x + 8, y + 8, 14, 10, WHITE)
    cv.line(x + 8, y + 8, x + 22, y + 18, RED2, 2)
    cv.line(x + 22, y + 8, x + 8, y + 18, RED2, 2)
    for sx, sy in ((12, 10), (26, 14), (32, 26), (16, 28)):
        cv.circle(x + w // 2 + sx, y + sy, 3, (255, 222, 0))
    cv.fill(x, y + h - int(h * 0.12), w, int(h * 0.12), GOLD)


def scene_bitcoin(cv, x, y, w, h):
    # Bitcoin coin, falling red chart, ether line, -3.9% tag.
    cv.fill(x, y, w, h, (16, 20, 32))
    cx, cy = x + int(w * 0.20), y + h // 2
    cv.circle(cx, cy, int(h * 0.44), (247, 147, 26))
    draw_text(cv, cx - text_w("B", "B26") // 2, cy - 9, "B", "B26", WHITE)
    pts = [(x + int(w * 0.36), y + 8), (x + int(w * 0.48), y + 14),
           (x + int(w * 0.60), y + 10), (x + int(w * 0.72), y + 24),
           (x + int(w * 0.84), y + 28), (x + w - 8, y + h - 10)]
    for a, b in zip(pts, pts[1:]):
        cv.line(a[0], a[1], b[0], b[1], RED2, 2)
    pts2 = [(x + int(w * 0.36), y + 16), (x + int(w * 0.52), y + 22),
            (x + int(w * 0.68), y + 20), (x + int(w * 0.84), y + 32)]
    for a, b in zip(pts2, pts2[1:]):
        cv.line(a[0], a[1], b[0], b[1], (120, 160, 255), 1)
    pct = "-3.9%"
    draw_text(cv, x + w - text_w(pct, "R16") - 4, y + h - 20, pct, "R16",
              (255, 120, 120))


def scene_f1(cv, x, y, w, h):
    # Chequered band, floodlights, red race car.
    cv.fill(x, y, w, h, (12, 12, 20))
    cs = max(8, int(h * 0.20))
    for i in range(0, w, cs):
        for j in (0, 1):
            if (i // cs + j) % 2 == 0:
                cv.fill(x + i, y + j * (cs // 2), cs, cs // 2, WHITE)
    for lx in (x + 14, x + w - 14):
        cv.circle(lx, y + int(h * 0.30), 4, (255, 240, 180))
        cv.line(lx, y + int(h * 0.30), lx, y + h - 10, (80, 80, 90), 1)
    cx, cy = x + w // 2, y + h // 2 + 8
    cv.fill(cx - 62, cy - 7, 124, 12, RED2)
    cv.poly([(cx - 24, cy - 7), (cx - 10, cy - 20), (cx + 26, cy - 20),
             (cx + 36, cy - 7)], RED2)
    cv.fill(cx - 70, cy - 16, 10, 10, RED2)
    cv.circle(cx - 36, cy + 7, 8, INK)
    cv.circle(cx + 36, cy + 7, 8, INK)
    cv.circle(cx - 36, cy + 7, 3, GREY)
    cv.circle(cx + 36, cy + 7, 3, GREY)


def scene_cricket(cv, x, y, w, h):
    # Green outfield, pitch, stumps, bat and ball, boundary rope.
    cv.fill(x, y, w, h, (40, 130, 60))
    cv.fill(x + w // 2 - 16, y, 32, h, (205, 175, 120))
    for yy in (8, h - 10):
        for xx in (-10, 0, 10):
            cv.fill(x + w // 2 + xx - 1, y + yy, 2, 7, (255, 230, 120))
    cv.circle(x + w // 2, y + 4, 2, WHITE)
    bx, by = x + w // 2 - 42, y + h // 2 - 5
    cv.fill(bx, by, 26, 6, (150, 105, 50))
    cv.fill(bx + 26, by + 1, 10, 4, (150, 105, 50))
    cv.circle(x + w // 2 + 36, y + h // 2 + 10, 5, RED2)
    cv.hline(x, y + h - 4, w, (240, 240, 240), 2)


