DATE_CHECK = (
    "DATE CHECK Left out as Friday 20 November\u2019s news: Wall "
    "Street\u2019s correction, the Kyiv bridges barrage, the missile "
    "in Poland, the UK-EU deal, Cyclone Akvan\u2019s landfall. Not "
    "confirmed when drawn: BepiColombo at Mercury, a final COP31 text."
)


def draw_map(cv, x, y, w, h):
    """Stylised world map with numbered pins for all 35 stories.

    Continents and pins are drawn in a 288x220 reference frame and
    scaled to (w, h).  Pin numbers match the story numbers on the
    page; clustered cities are nudged apart so the numbers stay
    readable.
    """
    cv.fill(x, y, w, h, NAVY)
    land = (222, 210, 170)
    sx = w / 288.0
    sy = h / 220.0
    polys = [
        # North America
        [(18, 38), (62, 22), (108, 30), (112, 58), (86, 78), (52, 72),
         (24, 58)],
        # Greenland
        [(120, 18), (132, 14), (136, 26), (124, 30)],
        # South America
        [(78, 92), (108, 88), (118, 118), (98, 152), (82, 128)],
        # UK
        [(132, 30), (138, 26), (140, 36), (134, 40)],
        # Europe
        [(138, 32), (164, 24), (176, 42), (156, 56), (138, 48)],
        # Africa
        [(140, 68), (168, 62), (180, 92), (162, 124), (144, 98)],
        # Asia
        [(178, 28), (248, 22), (266, 48), (242, 72), (202, 66),
         (184, 48)],
        # SE Asia peninsula
        [(228, 72), (240, 78), (236, 96), (226, 88)],
        # Japan
        [(252, 48), (258, 44), (260, 56), (254, 60)],
        # Australia
        [(232, 138), (264, 132), (270, 152), (240, 158)],
        # New Zealand
        [(272, 168), (278, 164), (280, 176), (274, 180)],
    ]
    for p in polys:
        cv.poly([(x + int(px * sx), y + int(py * sy)) for px, py in p],
                land)
    pins = [(158, 64, "1"), (176, 90, "2"), (75, 145, "3"),
            (158, 34, "4"), (192, 80, "5"), (186, 60, "6"),
            (76, 54, "7"), (232, 52, "8"), (240, 116, "9"),
            (255, 187, "10"), (128, 52, "11"), (46, 62, "12"),
            (276, 197, "13"), (174, 44, "14"), (140, 28, "15"),
            (146, 72, "16"), (170, 70, "17"), (162, 52, "18"),
            (160, 92, "19"), (64, 68, "20"), (88, 66, "21"),
            (44, 82, "22"), (32, 72, "23"), (58, 80, "24"),
            (34, 40, "25"), (242, 64, "26"), (250, 54, "27"),
            (236, 84, "28"), (222, 104, "29"), (200, 76, "30"),
            (210, 88, "31"), (206, 100, "32"), (182, 161, "33"),
            (244, 196, "34"), (56, 50, "35")]
    for px, py, n in pins:
        cxp = x + int(px * sx)
        cyp = y + int(py * sy)
        cv.circle(cxp, cyp, 7, RED2)
        draw_text(cv, cxp - text_w(n, "B12") // 2, cyp - 6, n, "B12",
                  WHITE)
    draw_text(cv, x + 6, y + h - 34, "Each number is", "R12", WHITE)
    draw_text(cv, x + 6, y + h - 19, "the story.", "R12", WHITE)


# ------------------------------------------------------------ layout
def build_image():
    cv = Canvas(W, H, PAPER)
    M = 20
    RW = W - 2 * M

    # Top strip.
    y = 8
    draw_text(cv, M, y, "THE WORLD IN ONE DAY", "B16", RED)
    right = "35 STORIES \u2022 7 REGIONS \u2022 EVERY ONE DATED"
    draw_text(cv, M + RW - text_w(right, "R16"), y, right, "R16", INK)
    y += line_h("R16")
    cv.hline(M, y, RW, INK, 2)
    y += 5

    # Huge date.
    date = "Saturday 21 November 2026"
    draw_text(cv, W // 2 - text_w(date, "D52") // 2, y, date, "D52", INK)
    y += line_h("D52")
    draw_text_centered(cv, W // 2, y,
                       "COP31 past deadline \u2022 Missiles shot down over "
                       "Saudi Arabia \u2022 Quake shakes Peru", "R16", INK)
    y += line_h("R16")
    cv.hline(M, y, RW, INK, 2)
    y += 5

    # Numbers row: 6 cells, 2-line captions.
    cw = RW // 6
    for i, (num, caps) in enumerate(NUMBERS):
        cx = M + i * cw
        draw_text(cv, cx + (cw - text_w(num, "B26")) // 2, y, num, "B26",
                  NAVY2)
        cy = y + line_h("B26") + 3
        for cap in caps:
            draw_text(cv, cx + (cw - text_w(cap, "R16")) // 2, cy, cap,
                      "R16", GREY)
            cy += line_h("R16")
        if i:
            cv.vline(cx, y + 2, 72, MIDGREY, 1)
    y += line_h("B26") + 3 + 2 * line_h("R16")

    # Region bar.
    rx = M
    for label, col in REGIONS:
        wch = text_w(label, "B16") + 16
        cv.fill(rx, y, wch, 20, col)
        draw_text(cv, rx + 8, y + 1, label, "B16", WHITE)
        rx += wch + 8
    y += 21

    # Three illustrated leads. v6: panels 104px, summaries 3 lines
    # at R14 with sources.
    LEAD_H = 104
    lw = (RW - 24) // 3
    lead_bottom = y
    for i, (banner, tag, kick, head, summ, scene) in enumerate(LEADS):
        lx = M + i * (lw + 12)
        scene(cv, lx, y, lw, LEAD_H)
        cv.fill(lx, y, text_w(banner, "B16") + 12, 20, RED)
        draw_text(cv, lx + 6, y + 1, banner, "B16", WHITE)
        cv.fill(lx, y + LEAD_H - 20, text_w(tag, "B16") + 12, 20, WHITE)
        draw_text(cv, lx + 6, y + LEAD_H - 19, tag, "B16", INK)
        ky = y + LEAD_H + 4
        draw_text(cv, lx, ky, kick, "B16", RED)
        hy = ky + line_h("B16") + 4
        n_head = len(wrap(head, lw, "B26"))
        draw_para(cv, lx, hy, head, lw, "B26", INK, leading=line_h("B26"))
        sy = hy + n_head * line_h("B26") + 4
        n_summ = len(wrap(summ, lw, "R14"))
        draw_para(cv, lx, sy, summ, lw, "R14", DARKGREY,
                  leading=line_h("R14"))
        lead_bottom = max(lead_bottom, sy + n_summ * line_h("R14"))
    y = lead_bottom + 4

    # Ten medium stories, 2 rows x 5. v6: pictures 54px with a red
    # banner on top and a verification chip bottom-right; summaries
    # 2 lines at R14 with sources.
    MED_H = 54
    mw = (RW - 40) // 5
    for row in range(2):
        for col in range(5):
            banner, kick, head, summ, chip, scene = MEDIUM[row * 5 + col]
            mx = M + col * (mw + 10)
            my = y + row * MED_PITCH
            scene(cv, mx, my, mw, MED_H)
            cv.fill(mx, my, text_w(banner, "B16") + 12, 18, RED)
            draw_text(cv, mx + 6, my + 1, banner, "B16", WHITE)
            cw_chip = text_w(chip, "B12") + 10
            cv.fill(mx + mw - cw_chip, my + MED_H - 15, cw_chip, 15,
                    WHITE)
            cv.rect(mx + mw - cw_chip, my + MED_H - 15, cw_chip, 15,
                    RED, 1)
            draw_text(cv, mx + mw - cw_chip + 5, my + MED_H - 14, chip,
                      "B12", RED)
            draw_text(cv, mx, my + MED_H + 2, kick, "B16", RED)
            hy = my + MED_H + 2 + line_h("B16") + 3
            n_head = len(wrap(head, mw, "B20"))
            draw_para(cv, mx, hy, head, mw, "B20", INK,
                      leading=line_h("B20"))
            sy = hy + n_head * line_h("B20") + 3
            n_summ = len(wrap(summ, mw, "R14"))
            draw_para(cv, mx, sy, summ, mw, "R14", DARKGREY,
                      leading=line_h("R14"))
    y += 2 * MED_PITCH + 4

    # Map + ALSO list: map 280x142, ALSO in 2 columns at R12.
    map_w, map_h = 280, 142
    ax = M + map_w + 16
    acw = (RW - map_w - 16) // 2
    draw_text(cv, M, y, "WHERE IT HAPPENED", "B16", RED)
    draw_text(cv, ax, y, "ALSO ON SATURDAY 21 NOVEMBER - 22 MORE STORIES",
              "B16", RED)
    y += line_h("B16")
    draw_map(cv, M, y, map_w, map_h)
    for i, item in enumerate(ALSO):
        ix = ax + (i // 11) * acw
        iy = y + (i % 11) * 13
        num = item.split(" ", 1)[0]
        rest = item[len(num) + 1:]
        draw_text(cv, ix, iy, num + " ", "B12", RED)
        draw_text(cv, ix + text_w(num + " ", "B12"), iy, rest, "R12",
                  INK)
    y += max(map_h, 11 * 13) + 2

    # DATE CHECK box.
    lines = wrap(DATE_CHECK, RW - 16, "R14")
    box_h = len(lines) * line_h("R14") + 6
    cv.rect(M, y, RW, box_h, RED, 2)
    ty = y + 3
    for ln in lines:
        draw_text(cv, M + 8, ty, ln, "R14", INK)
        ty += line_h("R14")
    y += box_h + 3

    # Footer: one line, attribution + original drawings.
    draw_text_centered(cv, W // 2, y,
                       "Every story happened, or was first reported, on "
                       "Saturday 21 November 2026. Sources named beside "
                       "each story \u2022 original drawings", "R14", INK)
    y += line_h("R14")
    print("final y:", y)
    return png_bytes(cv)


# Medium pitch: panel + kicker + 2-line headline + 2-line summary.
MED_PITCH = 54 + 2 + 19 + 3 + 2 * 24 + 3 + 2 * 16 + 6


def main():
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
    os.makedirs(outdir, exist_ok=True)
    data = build_image()
    with open(os.path.join(outdir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
